import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Stash and local search","description":"","frontmatter":{},"headers":[],"relativePath":"searchable/stash-and-search.md","filePath":"searchable/stash-and-search.md","lastUpdated":1793126588000}'),c={name:"searchable/stash-and-search.md"};function n(i,e,d,r,l,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="stash-and-local-search" tabindex="-1">Stash and local search <a class="header-anchor" href="#stash-and-local-search" aria-label="Permalink to &quot;Stash and local search&quot;">​</a></h1><p><code>web_stash</code> stores a normalized page as canonical JSON below:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.neottia/searchable/pages/&lt;sha256-of-normalized-url&gt;.json</span></span></code></pre></div><p>The record includes the format version, URL, title, content, <code>created_at</code>, <code>updated_at</code>, and optional excerpt, site, and source fields. Re-stashing the same normalized URL updates the same record. Canonical writes use <code>@neottia/repository-store</code> conflict and filesystem checks and honor <code>max_storage_bytes</code>.</p><p><code>.neottia/cache/searchable.sqlite</code> is a disposable FTS5 cache. It records the canonical snapshot generation and rebuilds from canonical files after a clean start, generation mismatch, integrity failure, or permitted stale cache. It is not authority and can be deleted while no Searchable process is using it.</p><p>The cache has a separate disk bound because FTS5 stores text and term indexes in SQLite pages and may use WAL files while rebuilding. Its limit is eight times <code>max_storage_bytes</code> plus 8 MiB for fixed SQLite schema and journal overhead. This cache allowance does not increase the canonical storage quota.</p><p><code>web_grep</code> converts the bounded query into literal FTS terms, ranks candidates with BM25, and reloads every result from canonical JSON. Returned snippets are bounded UTF-8 windows from canonical content, not cache-owned copies.</p><p>A stale cache follows <code>cache.stale_policy</code>:</p><ul><li><code>rebuild</code>: rebuild automatically</li><li><code>fail</code>: return <code>STASH_CACHE_REBUILD_REQUIRED</code></li><li><code>prompt</code>: Pi asks; MCP and OpenCode rebuild because they have no interactive confirmation channel</li></ul>',9)])])}const m=a(c,[["render",n]]);export{u as __pageData,m as default};
